self.KB_CONTENT["card:758075"]={"id":"card:758075","ty":"card","sourceId":"758075","title":"『單據性質建立作業【訂單管理系統】』的作業目的為何？","ver":"iGP","topic":"銷貨單","keywords":["銷貨單","發票","訂單","申報"],"y":"explain","answer":"如欲由銷貨單確認時自動產生某申報公司的銷項發票時，需於此作業先行設定。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
