self.KB_CONTENT["card:758039"]={"id":"card:758039","ty":"card","sourceId":"758039","title":"『申報書媒體資料產生作業』中的『應稅內含資料匯總後再推算稅額』為何？","ver":"iGP","topic":"營業稅","keywords":["營業稅","課稅別","稅額","申報"],"y":"other","answer":"* 指課稅別為「應稅內含」者，須匯總後再計算未稅金額及稅額。 延伸閱讀 WF營業稅流程解析說明 延伸閱讀 WF申報書媒體資料產生作業","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
