self.KB_CONTENT["card:753030"]={"id":"card:753030","ty":"card","sourceId":"753030","title":"『越南明細分類帳』中的『選擇排序』為何？","ver":"iGP","topic":"立沖帳目","keywords":["立沖帳目","明細","科目","編號"],"y":"other","answer":"* 選擇報表要依「科目編號」或「立沖帳目代號」作排序。* 若選擇「依立沖帳目代號」，才可輸入「選擇立沖帳目順序」、「選擇立沖帳目來源」、「選擇立沖帳目代號」等選項條件。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
