self.KB_CONTENT["card:783071"]={"id":"card:783071","ty":"card","sourceId":"783071","title":"『銀行資料查詢作業』的作業重點有哪些？","ver":"GP4以上","topic":"單身","keywords":["單身","權限","料單","銀行"],"y":"explain","answer":"■作業重點1.可查詢該銀行存款各種幣別之目前餘額。2.顯示欄位為幣別、原幣存款餘額、變動本幣餘額。3.抓取銀行帳號資料單身檔，前端條件為銀行代號、幣別符合選項條件。4.以幣別做排序。5.原幣存款餘額、變動本幣餘額為售價權限管制。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
