self.KB_CONTENT["field:817321"]={"id":"field:817321","ty":"field","sourceId":"817321","title":"憑證","ver":"AIGP","topic":"","keywords":[],"job":"資安管控異常及覆核通知設定作業ISAI10","code":"","answer":"憑證需點選【轉出EXCEL】或【轉出WORD】才會進行紀錄，一般列印憑證並不會進行紀錄 EX:『PROFORMA INVOICE 』(EPSR14)轉出EXCEL功能","file":"fields.jsonl"};
